#include "../charge_compiler/json.hpp"
#include "sparse_runs_v2.hpp"
#include <gmpxx.h>
#include <array>
#include <filesystem>
#include <unordered_map>
#include <set>
#include <iostream>
#include <omp.h>
#include <time.h>
using I=long long;using Point=std::array<I,2>;
static double now(){timespec t{};require(clock_gettime(CLOCK_BOOTTIME,&t)==0,"clock");return t.tv_sec+t.tv_nsec*1e-9;}
static mpq_class rational(const Json& row){mpq_class q(row.at(0).str()+"/"+row.at(1).str());q.canonicalize();return q;}
static long double approximate(const mpq_class& q){return std::stold(q.get_num().get_str())/std::stold(q.get_den().get_str());}
static I integer_parameter(const Json& value){if(std::holds_alternative<std::string>(value.value)){auto&s=value.str();require(!s.empty()&&s.find_first_not_of("0123456789")==std::string::npos,"decimal sheet parameter string");size_t used=0;I n=std::stoll(s,&used);require(used==s.size(),"complete sheet parameter");return n;}return value.integer();}
int main(int argc,char**argv){try{
 require(argc==2,"usage: compile_R_extension_G CONFIG");auto cfg=Json::read(argv[1]);double deadline=cfg.at("deadline_uptime").num();I threads=cfg.at("threads").integer(),limit=cfg.at("max_accumulator_entries").integer();require(threads>0&&threads<=16&&limit>=16&&limit<=1000000,"bounded extension G resources");std::unordered_map<std::string,uint32_t> ids;std::ifstream source(cfg.at("R_nodes").str());require(bool(source),"R voltage namespace");std::string line;I prior=0;while(std::getline(source,line)){auto row=Json::parse(line);I id=row.at(0).integer();require(id==prior+1&&ids.emplace(row.at(1).str(),id).second,"unique contiguous R voltage identities");prior=id;}require(source.eof(),"complete R namespace");const auto& names=ids;
 auto id=[&](const std::string& name){auto found=names.find(name);require(found!=names.end(),"extension voltage absent from spatial basis");return found->second;};
 auto out=std::filesystem::path(cfg.at("output").str());require(std::filesystem::create_directory(out),"fresh extension G output");auto& parts=cfg.at("R_parts").arr();std::vector<std::exception_ptr> errors(parts.size());std::vector<I> anchors(parts.size()),axes(parts.size()),zeros(parts.size()),constraints(parts.size()),stubs(parts.size()),unresolved(parts.size()),runs(parts.size()),tiles(parts.size());
 #pragma omp parallel for num_threads(threads)
 for(I part=0;part<I(parts.size());part++){try{
  std::ifstream input(parts[part].str());require(bool(input),"R mesh part");std::ofstream symbolic(out/("symbolic_"+std::to_string(part)+".jsonl"));require(bool(symbolic),"symbolic end ledger");std::unordered_map<uint64_t,sparse::Value> acc;acc.reserve(limit);
  auto add=[&](uint32_t a,uint32_t b,long double value){if(a>b)std::swap(a,b);acc[(uint64_t(a)<<32)|b].add(value);};
  auto edge=[&](uint32_t a,uint32_t b,const mpq_class& rho){require(a!=b&&rho>0,"finite positive end resistance");long double g=approximate(mpq_class(1000L)/rho);require(std::isfinite(g)&&g>0,"finite extension conductance");add(a,a,g);add(b,b,g);add(a,b,-g);};
  auto flush=[&](){if(acc.empty())return;std::vector<sparse::Record> records;records.reserve(acc.size());for(auto&[key,v]:acc)records.push_back({key,v.signed_sum.value(),v.absolute_sum.value(),v.terms});std::sort(records.begin(),records.end(),[](auto&a,auto&b){return a.key<b.key;});sparse::write((out/("part_"+std::to_string(part)+"_run_"+std::to_string(runs[part]++)+".bin")).string(),records);acc.clear();};
  std::string raw;while(std::getline(input,raw)){if(tiles[part]++%1000==0)require(now()<deadline,"extension G deadline");auto row=Json::parse(raw);auto& aux=row.at("auxiliary");auto kind=aux.at("kind").str(),group=row.at("native_group_id").str();auto native_prefix="_rmesh_"+group+"_";
   if(kind=="anchored_sheet"){
    anchors[part]++;I rho=integer_parameter(aux.at("nominal_sheet_milliohms_per_square"));require(rho>0&&rho<1000000000,"positive nominal anchored sheet");std::vector<Point> points;std::vector<uint32_t> global;std::set<uint32_t> native_nodes;auto prefix="_rmesh_sheet_"+group+"_"+std::to_string(row.at("tile_serial").integer())+":r1:";
    for(size_t i=0;i<row.at("points").arr().size();i++){Point p{row.at("points").at(i).at(0).integer(),row.at("points").at(i).at(1).integer()};require(std::abs(p[0])<100000000&&std::abs(p[1])<100000000,"bounded integer anchored coordinates");points.push_back(p);auto name=row.at("point_nodes").at(i).str();auto n=id(name);global.push_back(n);if(name.starts_with(native_prefix))native_nodes.insert(n);else require(name.starts_with(prefix),"local anchored latent namespace");}require(native_nodes.size()==1,"single native anchor protects native DC graph");
    std::map<std::pair<uint32_t,uint32_t>,mpq_class> local;
    for(auto& triangle:row.at("triangles").arr()){std::array<I,3> t;for(int k=0;k<3;k++){t[k]=triangle.at(k).integer();require(t[k]>=0&&size_t(t[k])<points.size(),"anchored triangle index");}auto a=points[t[0]],b=points[t[1]],c=points[t[2]];I det=(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);require(det>0,"positive anchored P1 triangle");I dx[3]{b[1]-c[1],c[1]-a[1],a[1]-b[1]},dy[3]{c[0]-b[0],a[0]-c[0],b[0]-a[0]};for(int i=0;i<3;i++)for(int j=0;j<3;j++){mpq_class q(mpz_class(long(dx[i]*dx[j]+dy[i]*dy[j])),mpz_class(long(2*det)));q.canonicalize();local[{global[t[i]],global[t[j]]}]+=q;}}
    std::map<uint32_t,mpq_class> sums;std::map<uint32_t,std::set<uint32_t>> graph;for(auto&[ij,q]:local){auto[a,b]=ij;require(local.count({b,a})&&local.at({b,a})==q,"symmetric anchored stiffness");sums[a]+=q;if(a!=b){require(q<=0,"nonnegative anchored edge conductance");if(q<0)graph[a].insert(b);}}for(auto&[n,q]:sums)require(q==0,"exact anchored constant nullspace");std::set<uint32_t> visited;std::vector<uint32_t> pending{*native_nodes.begin()};while(!pending.empty()){auto n=pending.back();pending.pop_back();if(!visited.insert(n).second)continue;for(auto b:graph[n])pending.push_back(b);}require(visited.size()==sums.size(),"all anchored latent states connected to one native port");
    for(auto&[ij,q]:local)if(ij.first<=ij.second&&q!=0){mpq_class g=q*1000L/long(rho);add(ij.first,ij.second,approximate(g));}
   }else if(kind=="nominal_axis_ends"){
    axes[part]++;for(auto& stub:aux.at("stubs").arr()){auto a=stub.at("endpoint_nodes").at(0).str(),b=stub.at("endpoint_nodes").at(1).str(),latent=stub.at("new_latent_node").str();require((a==latent&&b.starts_with(native_prefix))||(b==latent&&a.starts_with(native_prefix)),"end stub connects one native and one fresh state");edge(id(a),id(b),rational(stub.at("nominal_resistance_milliohms_exact")));stubs[part]++;}
   }else if(kind=="zero_R_symbolic_ends"){
    zeros[part]++;constraints[part]+=aux.at("constraints").arr().size();std::map<std::string,std::vector<Point>> faces;for(size_t i=0;i<row.at("points").arr().size();i++)faces[row.at("point_nodes").at(i).str()].push_back({row.at("points").at(i).at(0).integer(),row.at("points").at(i).at(1).integer()});auto sample=faces.begin()->second;require(sample.size()>=2,"zero-R basis face");int flow=sample[0][0]==sample[1][0]?0:1;auto&box=row.at("box");I width=box.at(3-flow).integer()-box.at(1-flow).integer();require(width>0,"positive zero-R sheet width");std::map<I,std::string> knots;for(auto&[name,points]:faces){I coordinate=points[0][flow];for(auto p:points)require(p[flow]==coordinate,"constant zero-R basis face");require(knots.emplace(coordinate,name).second,"unique zero-R basis knot");}
    auto prefix="_zero_R_"+group+"_"+std::to_string(row.at("tile_serial").integer());for(bool lower:{true,false}){auto end=lower?knots.begin():std::prev(knots.end());auto latent=prefix+(lower?":lo":":hi");if(end->second!=latent)continue;auto anchor=lower?std::next(end):std::prev(end);require(anchor->second.starts_with(native_prefix),"symbolic end has a native anchor");mpq_class square(mpz_class(long(std::abs(end->first-anchor->first))),mpz_class(long(width)));square.canonicalize();Json s=Json::object();s["native_group_id"]=group;s["tile_serial"]=row.at("tile_serial");s["private_endpoints"]=Json::Array{end->second,anchor->second};s["global_voltage_ids"]=Json::Array{I(id(end->second)),I(id(anchor->second))};s["resistance_squares_exact"]=Json::Array{square.get_num().get_str(),square.get_den().get_str()};s["requires_sheet_model_for_material"]=aux.at("raw_material");s["finite_conductance_assigned"]=false;symbolic<<s.dump()<<'\n';unresolved[part]++;}
   }else throw std::runtime_error("unknown R auxiliary model");if(I(acc.size())>=limit)flush();
  }require(input.eof(),"complete R auxiliary mesh read");flush();symbolic.close();require(bool(symbolic),"symbolic end ledger close");
 }catch(...){errors[part]=std::current_exception();}}
 for(auto&e:errors)if(e)std::rethrow_exception(e);auto total=[](auto&v){I n=0;for(auto a:v)n+=a;return n;};require(total(tiles)==cfg.at("expected_tiles").integer(),"complete R extension tile coverage");Json report=Json::object();report["R_tiles"]=total(tiles);report["anchored_sheet_tiles"]=total(anchors);report["native_axis_tiles_without_redundant_sheet_G"]=total(axes);report["finite_nominal_end_stubs"]=total(stubs);report["zero_R_axis_tiles"]=total(zeros);report["native_zero_constraints_not_duplicated"]=total(constraints);report["unresolved_symbolic_end_stubs"]=total(unresolved);report["sparse_runs"]=total(runs);report["threads"]=threads;report["native_DC_graph_preserved_by_single_anchor_extensions"]=true;report["full_spatial_G_matrix_assembled"]=false;report["physical_RC_qualified"]=false;report["release_qualified"]=false;std::cout<<report.dump()<<'\n';return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
